message.content:
这是为您生成的一页「品牌定位」预览 HTML，以虚构测评资料为唯一事实来源，延续了参考页的纸感底色与细线装饰。页面把社区咖啡定位、三个关键词和品牌口号做了清晰铺排，右下角标注页码，适合直接用于内部对齐演示。
```html
<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<style>
  html,body{margin:0;padding:0;width:1920px;height:1080px;overflow:hidden;background:#F5F2E9}
  *{box-sizing:border-box}
  :root{
    --bg:#F5F2E9;
    --surface:#F3F0E7;
    --ink:#1B2620;
    --muted:#5C665D;
    --primary:#4F5E43;
    --secondary:#B4914A;
    --tertiary:#8C9FB2;
    --line:#A3AC9E;
    --serif:"Noto Serif SC","Source Han Serif SC","Songti SC","SimSun",Georgia,serif;
    --sans:"PingFang SC","Hiragino Sans GB","Microsoft YaHei","Noto Sans SC","Helvetica Neue",Arial,sans-serif;
  }
  .slide{
    position:relative;width:1920px;height:1080px;overflow:hidden;
    background:var(--bg);font-family:var(--sans);color:var(--ink);
  }

  /* ---------- background field ---------- */
  .bg{position:absolute;inset:0;z-index:0;
    background:
      radial-gradient(1100px 780px at 2% 0%, rgba(180,145,74,.10), transparent 70%),
      radial-gradient(880px 760px at 47% 46%, rgba(140,159,178,.10), transparent 70%),
      radial-gradient(950px 760px at 95% 95%, rgba(79,94,67,.11), transparent 72%),
      linear-gradient(168deg,#F8F5EC 0%,#F5F2E9 52%,#EFECE1 100%);
  }
  .bg:after{content:"";position:absolute;inset:0;
    background:repeating-linear-gradient(90deg,rgba(27,38,32,.038) 0 1px,transparent 1px 160px);
  }
  .dots{position:absolute;z-index:1;left:1428px;top:62px;width:396px;height:156px;opacity:.30;
    background-image:radial-gradient(circle,rgba(27,38,32,.45) 1.05px,transparent 1.15px);
    background-size:14px 14px;
  }
  .prism{position:absolute;z-index:1;left:1724px;top:-200px;width:112px;height:1320px;
    transform:rotate(14deg);transform-origin:top left;
    background:linear-gradient(180deg,rgba(140,159,178,.20),rgba(140,159,178,.05) 72%,rgba(140,159,178,0));
  }
  .prism:after{content:"";position:absolute;left:72px;top:0;width:40px;height:1320px;background:rgba(255,255,255,.34)}

  .gl{position:absolute;z-index:2;background:rgba(27,38,32,.055)}
  .gl1{left:480px;top:0;width:1px;height:1080px}
  .gl2{left:960px;top:0;width:1px;height:1080px}
  .gl3{left:1440px;top:0;width:1px;height:1080px}

  .top-rule{position:absolute;left:96px;top:48px;width:1728px;height:1px;z-index:6;background:rgba(27,38,32,.34)}
  .left-rule{position:absolute;left:60px;top:40px;width:1px;height:1000px;z-index:6;background:rgba(27,38,32,.24)}
  .top-meta{position:absolute;left:98px;top:62px;z-index:15;font-size:15px;font-weight:600;letter-spacing:4px;color:#4f5b53}
  .rail-label{position:absolute;left:44px;top:560px;width:420px;z-index:15;
    transform:rotate(-90deg);transform-origin:left top;
    font-size:13px;font-weight:600;letter-spacing:5px;color:#637067;white-space:nowrap}

  /* ---------- header ---------- */
  .head{position:absolute;left:96px;top:150px;width:1300px;z-index:6}
  .eyebrow{display:flex;align-items:center;gap:14px;font-size:15px;font-weight:600;
    letter-spacing:4.4px;color:#6b766c}
  .eyebrow .mark{display:inline-block;width:26px;height:2px;background:var(--secondary)}
  .title{margin:22px 0 0;font-family:var(--serif);font-size:104px;line-height:1.04;
    font-weight:600;letter-spacing:3px;color:#1B2620}
  .lede{margin:26px 0 0;font-size:26px;line-height:1.5;letter-spacing:1px;color:var(--muted)}
  .head-rule{position:absolute;left:96px;top:404px;width:1728px;height:1px;z-index:4;
    background:linear-gradient(90deg,rgba(27,38,32,.30),rgba(27,38,32,.10) 60%,rgba(27,38,32,0))}

  /* ---------- keywords ---------- */
  .keywords{position:absolute;left:96px;top:440px;width:1728px;display:flex;gap:36px;z-index:6}
  .kw{position:relative;flex:1;height:268px;padding:34px 42px 36px;
    display:flex;flex-direction:column;justify-content:space-between;
    background:linear-gradient(180deg,rgba(255,255,255,.64),rgba(243,240,231,.32));
    border:1px solid rgba(27,38,32,.10)}
  .kw:before{content:"";position:absolute;left:0;top:0;width:100%;height:3px;background:var(--primary)}
  .kw:nth-child(2):before{background:var(--secondary)}
  .kw:nth-child(3):before{background:var(--tertiary)}
  .kw-no{font-size:13px;font-weight:600;letter-spacing:4.5px;color:#8a938b}
  .kw-word{font-family:var(--serif);font-size:62px;line-height:1.1;font-weight:600;
    letter-spacing:5px;color:#1B2620}
  .kw-foot{display:flex;align-items:center;gap:12px}
  .kw-foot i{display:block;width:42px;height:1px;background:rgba(27,38,32,.35)}
  .kw-foot span{font-size:13px;letter-spacing:3px;color:#8a938b}

  /* ---------- slogan ---------- */
  .slogan{position:absolute;left:96px;top:748px;width:1168px;height:212px;z-index:6;
    padding:34px 44px;display:flex;flex-direction:column;justify-content:center;gap:16px;
    background:linear-gradient(118deg,rgba(79,94,67,.11),rgba(79,94,67,.025));
    border-left:4px solid var(--primary);
  }
  .slogan-label{font-size:13px;font-weight:600;letter-spacing:5px;color:var(--primary)}
  .slogan-text{font-family:var(--serif);font-size:68px;line-height:1.15;font-weight:600;
    letter-spacing:2px;color:#1B2620}
  .slogan-quote{position:absolute;right:44px;bottom:-6px;font-family:Georgia,serif;
    font-size:180px;line-height:1;color:rgba(140,159,178,.22);pointer-events:none}

  /* ---------- note ---------- */
  .note{position:absolute;left:1300px;top:748px;width:524px;height:212px;z-index:6;
    padding:32px 40px;background:rgba(180,145,74,.09);border:1px solid rgba(180,145,74,.38)}
  .note-tag{font-size:13px;font-weight:600;letter-spacing:5px;color:#8b6c2f}
  .note-text{margin:18px 0 0;font-size:23px;line-height:1.72;letter-spacing:1px;color:#2c362e}

  /* ---------- footer ---------- */
  .foot{position:absolute;left:96px;top:992px;z-index:15;display:flex;align-items:center;gap:14px;
    font-size:14px;letter-spacing:2.4px;color:#7a847b}
  .foot i{display:block;width:34px;height:1px;background:rgba(27,38,32,.35)}
  .page-no{position:absolute;right:96px;bottom:44px;z-index:15;
    font-size:15px;font-weight:600;letter-spacing:3px;color:#5f6a61}
</style>
</head>
<body>
<main class="slide">
  <div class="bg"></div>
  <div class="prism"></div>
  <div class="dots"></div>
  <div class="gl gl1"></div>
  <div class="gl gl2"></div>
  <div class="gl gl3"></div>

  <div class="top-rule"></div>
  <div class="left-rule"></div>
  <div class="top-meta">品牌传播 · 内部对齐资料</div>
  <div class="rail-label">溪木咖啡 · 品牌传播</div>

  <header class="head">
    <div class="eyebrow"><span class="mark"></span>品牌与门店运营团队 · 内部对齐</div>
    <h1 class="title">品牌定位</h1>
    <p class="lede">虚构的社区咖啡品牌，面向社区日常场景</p>
  </header>
  <div class="head-rule"></div>

  <section class="keywords">
    <article class="kw">
      <div class="kw-no">01</div>
      <div class="kw-word">日常</div>
      <div class="kw-foot"><i></i><span>定位关键词</span></div>
    </article>
    <article class="kw">
      <div class="kw-no">02</div>
      <div class="kw-word">友好</div>
      <div class="kw-foot"><i></i><span>定位关键词</span></div>
    </article>
    <article class="kw">
      <div class="kw-no">03</div>
      <div class="kw-word">易理解</div>
      <div class="kw-foot"><i></i><span>定位关键词</span></div>
    </article>
  </section>

  <section class="slogan">
    <div class="slogan-label">品牌口号</div>
    <div class="slogan-text">把日常慢慢喝好</div>
    <div class="slogan-quote">&rdquo;</div>
  </section>

  <aside class="note">
    <div class="note-tag">口径基准</div>
    <p class="note-text">本页为全篇口径基准，<br>后续页面不另行引申</p>
  </aside>

  <div class="foot"><i></i>资料依据：brand.docx（虚构测评材料）</div>
  <div class="page-no">2 / 6</div>
</main>
</body>
</html>
```
